from sage.all_cmdline import *   # import sage library

_sage_const_1 = Integer(1); _sage_const_40 = Integer(40); _sage_const_10 = Integer(10); _sage_const_16 = Integer(16); _sage_const_4 = Integer(4); _sage_const_9 = Integer(9); _sage_const_160 = Integer(160); _sage_const_3 = Integer(3); _sage_const_2000 = Integer(2000); _sage_const_11 = Integer(11); _sage_const_31 = Integer(31); _sage_const_43 = Integer(43); _sage_const_127 = Integer(127); _sage_const_23 = Integer(23); _sage_const_19 = Integer(19); _sage_const_59 = Integer(59); _sage_const_71 = Integer(71); _sage_const_83 = Integer(83); _sage_const_47 = Integer(47); _sage_const_67 = Integer(67); _sage_const_22 = Integer(22); _sage_const_0 = Integer(0); _sage_const_2 = Integer(2); _sage_const_1p27 = RealNumber('1.27'); _sage_const_24 = Integer(24); _sage_const_5000 = Integer(5000); _sage_const_32 = Integer(32)
import sys
import time
from multiprocessing import Process, Event

def precompute_V():
    V = {_sage_const_1 }
    for s in range(_sage_const_40 ):
        fs = (_sage_const_10  * _sage_const_16 **s + _sage_const_16  * _sage_const_4 **s + _sage_const_10 ) // _sage_const_9 
        for i in range(_sage_const_160 ):
            val = fs * _sage_const_4 **i
            V.add(val)
    return sorted(list(V))

all_V = precompute_V()
small_primes = [p for p in prime_range(_sage_const_3 , _sage_const_2000 ) if p % _sage_const_4  == _sage_const_3 ]

# 12 base primes
selected_primes = [_sage_const_3 , _sage_const_11 , _sage_const_31 , _sage_const_43 , _sage_const_127 , _sage_const_23 , _sage_const_19 , _sage_const_59 , _sage_const_71 , _sage_const_83 , _sage_const_47 , _sage_const_67 ]

# Optimize residues for N up to 10^22
N_max = _sage_const_10 **_sage_const_22 
limit = N_max * N_max
V_target = [v for v in all_V if v < limit]
print(f"V_target size for 10^22: {len(V_target)}")

selected_residues = {}
uncovered = list(V_target)

for p in selected_primes:
    cov_for_r = [_sage_const_0 ] * p
    for v in uncovered:
        v_mod = v % p
        if v_mod == _sage_const_0 :
            cov_for_r[_sage_const_0 ] += _sage_const_1 
        elif pow(v_mod, (p-_sage_const_1 )//_sage_const_2 , p) == _sage_const_1 :
            for r in range(_sage_const_1 , p):
                if (r*r) % p == v_mod:
                    cov_for_r[r] += _sage_const_1 
                    cov_for_r[p-r] += _sage_const_1 
                    break
    max_cov = max(cov_for_r)
    best_r = cov_for_r.index(max_cov)
    selected_residues[p] = best_r
    
    # Remove covered
    new_uncovered = []
    r2 = (best_r * best_r) % p
    for v in uncovered:
        if v % p != r2:
            new_uncovered.append(v)
    uncovered = new_uncovered

moduli = [_sage_const_2 ] + selected_primes
residues = [_sage_const_1 ] + [selected_residues[p] for p in selected_primes]
from math import prod as math_prod
base_prod = math_prod(moduli)
N0 = int(crt(residues, moduli))

print(f"CRT base: N0 = {N0}")
print(f"prod = {base_prod} (digits: {len(str(base_prod))})")

def is_blocked_fast(diff):
    for p in selected_primes:
        if diff % p == _sage_const_0 :
            if diff % (p*p) != _sage_const_0 :
                return p
    for p in small_primes:
        if diff % p == _sage_const_0 :
            if diff % (p*p) != _sage_const_0 :
                return p
    # Fallback to Sage factor
    factors = factor(diff)
    for p, exp in factors:
        if p % _sage_const_4  == _sage_const_3  and exp % _sage_const_2  != _sage_const_0 :
            return int(p)
    return None

def check_candidate(N):
    N2 = N * N
    V_actual = [v for v in all_V if v < N2]
    
    blocking_primes = {}
    for v in V_actual:
        p = is_blocked_fast(N2 - v)
        if p is None:
            return None
        blocking_primes[v] = p
    return blocking_primes

def worker(worker_id, k_start, k_end, shutdown_event):
    print(f"Worker {worker_id} started: k in [{k_start}, {k_end}]", flush=True)
    last_print = time.time()
    
    for k in range(k_start, k_end):
        if shutdown_event.is_set():
            break
            
        N = N0 + k * base_prod
        if N <= _sage_const_1 :
            continue
        if N >= _sage_const_1p27  * _sage_const_10 **_sage_const_24 :
            break
            
        bp = check_candidate(N)
        if bp is not None:
            print(f"\nSUCCESS! Worker {worker_id} found counterexample N = {N} (k = {k})", flush=True)
            print(f"N^2 = {N*N}", flush=True)
            print(f"V_all size = {len([v for v in all_V if v < N*N])}", flush=True)
            print(f"blocking_primes = {bp}", flush=True)
            
            # Save results
            with open("/workspace/leanproject/Submission/success_sage_found.py", "w") as f:
                f.write(f"N = {N}\n")
                f.write(f"blocking_primes = {bp}\n")
            shutdown_event.set()
            break

if __name__ == "__main__":
    k_max = _sage_const_5000 
    num_workers = _sage_const_32 
    step = k_max // num_workers
    
    shutdown_event = Event()
    processes = []
    
    start_time_global = time.time()
    
    for i in range(num_workers):
        w_start = i * step
        w_end = (i+_sage_const_1 ) * step if i < num_workers - _sage_const_1  else k_max
        p = Process(target=worker, args=(i, w_start, w_end, shutdown_event))
        processes.append(p)
        p.start()
        
    try:
        while not shutdown_event.is_set():
            alive = False
            for p in processes:
                if p.is_alive():
                    alive = True
                    break
            if not alive:
                print("All processes finished search.", flush=True)
                break
            time.sleep(_sage_const_1 )
    except KeyboardInterrupt:
        print("Interrupted! Terminating processes...")
        shutdown_event.set()
        
    for p in processes:
        p.join(timeout=_sage_const_1 )
        if p.is_alive():
            p.terminate()
            
    print(f"Done in {time.time() - start_time_global:.2f}s.", flush=True)

